    ROW_NUMBER() OVER (
        PARTITION BY l.COMPANY_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls._AIRBYTE_EXTRACTED_AT
    ) AS row_num

FROM {{ source('eli_dv_bv', 'lna_company_company_dwbhidc') }} l
